// === Tab: mySketch ===
// ########################################################## //
// #                                                        # //
// #            Test for post processing shaders            # //
// #                                                        # //
// ########################################################## //
// #                                                        # //
// #                Written by Fabian Kober                 # //
// #                  fabian-kober@gmx.net                  # //
// #                                                        # //
// ########################################################## //

// speed of the wobble
let speed = 1;

// tiling of the wobble
let tiling = 10;

// stength of the wobble
let strength = 2;

// the shader
let sh;

// an image
let img;

let vert = 'attribute vec4 aPosition;'+
'varying vec4 v_uv;'+
'void main() {'+
'v_uv = aPosition;'+
'v_uv.y *= -1.0;'+
'v_uv.x = v_uv.x * 0.5 + 0.5;'+
'v_uv.y = v_uv.y * 0.5 + 0.5;'+ 
    'gl_Position = aPosition;'+
'}';

let frag = 'precision mediump float;'+

'uniform sampler2D uSampler;'+
'uniform float u_time;'+

'uniform float u_speed;'+
'uniform float u_tiling;'+
'uniform float u_strength;'+

'varying vec4 v_uv;'+

'void main() {'+
'vec2 texcoord = vec2(v_uv.x-sin(u_time*u_speed)*0.05*tan(v_uv.y*u_tiling)*u_strength, v_uv.y-cos(u_time*u_speed)*0.05*sin(v_uv.x*u_tiling)*u_strength);'+
'vec4 col = texture2D(uSampler, texcoord);'+
'gl_FragColor = col;'+
'}'

function preload() {
    // load the image
    img = loadImage('https://images.pexels.com/photos/45201/kitty-cat-kitten-pet-45201.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=750&w=1260');
}

function setup() {
    createCanvas(500, 500, WEBGL);
    sh = createShader(vert, frag);
		background(0);
}

function draw() {
    // set uniforms
    sh.setUniform("uSampler", img);
    sh.setUniform("u_time", millis()/1000);
    sh.setUniform("u_speed", speed);
    sh.setUniform("u_tiling", tiling+(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))*0.01);
    sh.setUniform("u_strength", strength+(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))*0.01);

    // render on a quad
    shader(sh);
    quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

